"use client";

import { Toaster as Sonner, type ToasterProps } from "sonner";
import { cn } from "@/lib/utils";
import "./liquid.css";

export { toast } from "sonner";

/** Sonner owns announcements, timers, stacking and swipe dismissal. */
export function Toaster({ className, toastOptions, ...props }: ToasterProps) {
  return <Sonner
    position="top-center"
    offset={{ top: "max(20px, env(safe-area-inset-top))" }}
    mobileOffset={{ top: "max(16px, env(safe-area-inset-top))", left: 16, right: 16 }}
    visibleToasts={3}
    closeButton
    className={cn("liquid-toaster", className)}
    {...props}
    toastOptions={{
      ...toastOptions,
      classNames: {
        ...toastOptions?.classNames,
        toast: cn("liquid-surface liquid-toast", toastOptions?.classNames?.toast),
      },
    }}
  />;
}

.liquid-surface {
  --liquid-blur: 20px;
  --liquid-tint: .22;
  --liquid-ink: #172323;
  --liquid-fill: 255 255 255;
  position: relative;
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / var(--liquid-tint));
  border: 1px solid rgb(255 255 255 / .65);
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  box-shadow: inset 0 1px 1px rgb(255 255 255 / .9), inset 0 -1px 1px rgb(255 255 255 / .25), inset 2px 0 5px rgb(255 255 255 / .18), 0 8px 28px rgb(0 20 25 / .14);
  transition: background 200ms ease, box-shadow 200ms ease;
}
.liquid-surface:focus-visible, .liquid-tab:focus-visible, .liquid-toolbar-button:focus-visible { outline: 3px solid #007aff; outline-offset: 4px; }
.liquid-interactive {
  position: relative;
  isolation: isolate;
  translate: var(--liquid-x, 0px) var(--liquid-y, 0px);
  scale: var(--liquid-scale-x, 1) var(--liquid-scale-y, 1);
  /* The spring owns translate/scale; consumers still own transform. */
  transition: background 200ms ease, box-shadow 200ms ease;
}
.liquid-interactive::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(ellipse at var(--liquid-light-x, 50%) var(--liquid-light-y, 25%), rgb(255 255 255 / .48), rgb(255 255 255 / .07) 45%, transparent 72%);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / .28);
  opacity: var(--liquid-light, 0);
  z-index: -1;
}
.liquid-button { border-radius: 999px; min-height: 44px; font-weight: 600; padding-inline: 24px; }
.liquid-button:hover:not(:disabled) { background: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + .1)); box-shadow: inset 0 1px 2px white, inset 0 -1px 2px rgb(190 224 255 / .5), 0 12px 32px rgb(0 20 25 / .2); }
.liquid-button[data-size^="icon"] { padding-inline: 0; }
.liquid-button[data-liquid-variant="destructive"] { --liquid-ink: #a20c22; --liquid-fill: 255 200 208; }
.liquid-button[data-liquid-variant="ghost"], .liquid-button[data-liquid-variant="link"] { border-color: transparent; box-shadow: none; background: transparent; backdrop-filter: none; }
.liquid-button[data-liquid-variant="link"] { text-decoration: underline; }
.liquid-button[data-liquid-variant="secondary"] { background: rgb(var(--liquid-fill) / .55); }
.liquid-button[data-state="open"] > svg { rotate: 180deg; }
.liquid-button > svg { transition: rotate 350ms cubic-bezier(.2,.8,.2,1); }
.liquid-tabs { border-radius: 999px; padding: 5px; height: 52px; gap: 3px; isolation: isolate; }
.liquid-tabs[data-orientation="vertical"] { height: auto; border-radius: 26px; }
.liquid-tab { position: relative; color: var(--liquid-ink); border-radius: 999px; padding-inline: 22px; height: 40px; background: transparent; transition: color 180ms ease; }
.liquid-tab[data-state="active"] { color: var(--liquid-ink); background: rgb(var(--liquid-fill) / .58); box-shadow: 0 2px 8px rgb(0 0 0 / .12), inset 0 1px 1px rgb(255 255 255 / .8); }
.liquid-tabs[data-liquid-indicator] .liquid-tab[data-state="active"] { background: transparent; box-shadow: none; }
.liquid-tabs::before, .liquid-toolbar::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: var(--liquid-indicator-width, 0px);
  height: var(--liquid-indicator-height, 0px);
  transform: translate(var(--liquid-indicator-x, 0px), var(--liquid-indicator-y, 0px)) scale(var(--liquid-indicator-scale-x, 1), var(--liquid-indicator-scale-y, 1));
  border-radius: 999px;
  background: linear-gradient(135deg, rgb(255 255 255 / .28), transparent 50%, rgb(195 227 255 / .12)), rgb(var(--liquid-fill) / .38);
  border: 1px solid rgb(255 255 255 / .6);
  box-shadow: inset 0 1px 2px rgb(255 255 255 / .85), inset 0 -1px 2px rgb(255 255 255 / .25), 0 3px 10px rgb(0 20 25 / .12);
  pointer-events: none;
  opacity: 0;
  z-index: -1;
}
.liquid-tabs[data-liquid-indicator]::before, .liquid-toolbar[data-liquid-indicator]::before { opacity: 1; }
.liquid-tab:hover:not(:disabled) { color: var(--liquid-ink); }
.liquid-menu {
  --liquid-menu-x: 0px;
  --liquid-menu-y: -10px;
  --liquid-menu-scale-x: .8;
  --liquid-menu-scale-y: .6;
  border-radius: 22px;
  padding: 6px;
  min-width: 220px;
  background: rgb(var(--liquid-fill) / max(var(--liquid-tint), .68));
  transform-origin: center;
  transition: background 200ms ease;
}
.liquid-menu [role^="menuitem"] { min-height: 40px; border-radius: 15px; color: inherit; transition: background 140ms ease; }
.liquid-menu [role^="menuitem"][data-highlighted] { background: rgb(0 122 255 / .16); }
.liquid-menu [data-variant="destructive"] { color: #c52238; }
.liquid-menu[data-state="open"]:not([data-liquid-morph="ready"]) { opacity: 0; }
.liquid-menu[data-state="open"][data-liquid-morph="ready"] { animation: liquid-menu-unfold var(--liquid-morph-duration, 520ms) both; }
.liquid-menu[data-state="open"][data-liquid-morph="ready"] > * { animation: liquid-content-in var(--liquid-morph-duration, 520ms) both; }
.liquid-menu[data-state="closed"] { animation: liquid-menu-fold 180ms cubic-bezier(.4,0,.7,.2) both; pointer-events: none; }
.liquid-menu[data-state="closed"] > * { opacity: 0; }
@keyframes liquid-menu-unfold {
  0% { opacity: 0; transform: translate(var(--liquid-menu-x), var(--liquid-menu-y)) scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y)); border-radius: 70px; animation-timing-function: cubic-bezier(.16,1,.3,1); }
  65% { opacity: 1; transform: translate(0, 0) scale(1.025, 1.04); border-radius: 20px; animation-timing-function: cubic-bezier(.3,0,.2,1); }
  100% { opacity: 1; transform: translate(0, 0) scale(1); border-radius: 22px; }
}
@keyframes liquid-content-in { 0%, 20% { opacity: 0; filter: blur(3px); } 65%, 100% { opacity: 1; filter: blur(0); } }
@keyframes liquid-menu-fold {
  from { opacity: 1; transform: translate(0, 0) scale(1); border-radius: 22px; }
  to { opacity: 0; transform: translate(var(--liquid-menu-x), var(--liquid-menu-y)) scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y)); border-radius: 70px; }
}
.liquid-toolbar { display: flex; align-items: center; padding: 6px; border-radius: 999px; gap: 4px; isolation: isolate; }
.liquid-toolbar[data-orientation="vertical"] { flex-direction: column; }
.liquid-toolbar-button { display: grid; place-items: center; width: 44px; height: 44px; border: 0; border-radius: 50%; background: transparent; color: inherit; }
.liquid-toolbar-button svg { width: 21px; height: 21px; }
.liquid-toolbar-button:hover:not(:disabled), .liquid-toolbar-button[aria-pressed="true"] { background: rgb(255 255 255 / .18); }
.liquid-toolbar[data-liquid-indicator] .liquid-toolbar-button[aria-pressed="true"] { background: transparent; }
.liquid-toolbar-button:disabled { opacity: .5; }
.liquid-toolbar-separator { height: 20px; width: 1px; background: rgb(255 255 255 / .4); margin-inline: 3px; }
.liquid-toolbar-separator[data-orientation="horizontal"] { height: 1px; width: 20px; margin: 3px 0; }
.dark .liquid-surface, [data-liquid-theme="dark"] .liquid-surface { --liquid-fill: 22 27 30; --liquid-ink: #fff; border-color: rgb(255 255 255 / .3); }
[data-reduced-transparency="true"] .liquid-surface { background: rgb(var(--liquid-fill)); -webkit-backdrop-filter: none; backdrop-filter: none; }
@supports not (backdrop-filter: blur(1px)) { .liquid-surface { background: rgb(var(--liquid-fill) / .96); } }
@media (prefers-reduced-transparency: reduce), (prefers-contrast: more) { .liquid-surface { background: rgb(var(--liquid-fill)); -webkit-backdrop-filter: none; backdrop-filter: none; } }
[data-reduced-motion="true"] .liquid-surface, [data-reduced-motion="true"] .liquid-interactive, [data-reduced-motion="true"] .liquid-menu > *, [data-reduced-motion="true"] .liquid-button > svg { transition: none !important; animation: none !important; }
[data-reduced-motion="true"] .liquid-interactive { translate: none; scale: none; }
[data-reduced-motion="true"] .liquid-menu[data-state="open"] { opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  .liquid-surface, .liquid-tab, .liquid-interactive, .liquid-menu > *, .liquid-button > svg { transition: none !important; animation: none !important; }
  .liquid-interactive { translate: none; scale: none; }
  .liquid-menu[data-state="open"] { opacity: 1; }
}
@media (forced-colors: active) { .liquid-surface { border: 1px solid ButtonText; } .liquid-tabs::before, .liquid-toolbar::before { background: Highlight; border-color: Highlight; } }
/* Liquid notifications. Keep Sonner's transform for stacking and swipe gestures. */
.liquid-toaster [data-sonner-toast].liquid-toast {
  position: absolute;
  width: var(--width);
  padding: 18px 44px 18px 18px;
  gap: 12px;
  border-radius: 28px;
  border: 1px solid rgb(255 255 255 / .8);
  color: var(--liquid-ink);
  background: linear-gradient(135deg, rgb(255 255 255 / .18), transparent 60%), rgb(var(--liquid-fill) / max(var(--liquid-tint), .72));
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.8);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.8);
  box-shadow: inset 0 1px 1px rgb(255 255 255 / .95), inset 0 -1px 1px rgb(255 255 255 / .3), 0 12px 36px rgb(0 20 25 / .15), 0 2px 8px rgb(0 20 25 / .05);
  scale: .45 .7;
  transform-origin: top center;
  transition: transform 520ms cubic-bezier(.2,.9,.25,1.15), scale 520ms cubic-bezier(.2,.9,.25,1.15), opacity 180ms ease, height 380ms cubic-bezier(.2,.9,.25,1.1), border-radius 420ms ease, box-shadow 200ms ease;
}
.liquid-toaster [data-sonner-toast].liquid-toast[data-mounted="true"] { scale: 1; }
.liquid-toaster [data-sonner-toast].liquid-toast[data-mounted="false"] { border-radius: 60px; }
.liquid-toaster [data-sonner-toast].liquid-toast[data-removed="true"][data-swipe-out="false"] { scale: .55 .75; border-radius: 60px; transition-duration: 180ms; }
.liquid-toaster .liquid-toast [data-content] { gap: 4px; min-width: 0; }
.liquid-toaster .liquid-toast [data-title] { font-size: 13px; font-weight: 600; line-height: 1.45; letter-spacing: -.01em; }
.liquid-toaster .liquid-toast [data-description] { font-size: 12px; line-height: 1.5; color: inherit; opacity: .65; overflow-wrap: anywhere; }
.liquid-toaster .liquid-toast [data-icon] { align-self: center; margin: 0; width: 26px; height: 26px; flex-shrink: 0; justify-content: center; }
.liquid-toaster .liquid-toast [data-icon] svg { width: 20px; height: 20px; }
.liquid-toaster .liquid-toast[data-type="success"] [data-icon] { color: #168451; }
.liquid-toaster .liquid-toast[data-type="error"] [data-icon] { color: #cf3445; }
.liquid-toaster .liquid-toast[data-type="warning"] [data-icon] { color: #ac6a0b; }
.liquid-toaster .liquid-toast[data-type="info"] [data-icon] { color: #007aff; }
.liquid-toaster .liquid-toast [data-content], .liquid-toaster .liquid-toast [data-icon], .liquid-toaster .liquid-toast [data-button] { opacity: 0; filter: blur(2px); transition: opacity 180ms ease 100ms, filter 260ms ease 80ms; }
.liquid-toaster .liquid-toast[data-mounted="true"] [data-content], .liquid-toaster .liquid-toast[data-mounted="true"] [data-icon], .liquid-toaster .liquid-toast[data-mounted="true"] [data-button] { opacity: 1; filter: blur(0); }
.liquid-toaster .liquid-toast[data-removed="true"] [data-content], .liquid-toaster .liquid-toast[data-removed="true"] [data-icon] { opacity: 0; transition-delay: 0ms; }
.liquid-toaster .liquid-toast[data-expanded="false"][data-front="false"] > * { opacity: 0; }
.liquid-toaster [data-sonner-toast].liquid-toast [data-close-button] {
  left: auto; right: 12px; top: 50%; transform: translateY(-50%);
  width: 24px; height: 24px; border-radius: 50%;
  color: inherit; background: rgb(var(--liquid-fill) / .4); border: 1px solid rgb(128 128 128 / .12);
}
.liquid-toaster [data-sonner-toast].liquid-toast [data-close-button]:hover { background: rgb(var(--liquid-fill) / .85); }
.liquid-toaster .liquid-toast [data-button] { border-radius: 999px; }
.dark .liquid-toaster .liquid-toast, [data-liquid-theme="dark"] .liquid-toaster .liquid-toast { border-color: rgb(255 255 255 / .25); }
.dark .liquid-toaster .liquid-toast[data-type="success"] [data-icon], [data-liquid-theme="dark"] .liquid-toaster .liquid-toast[data-type="success"] [data-icon] { color: #6ddeac; }
[data-reduced-transparency="true"] .liquid-toaster .liquid-toast { background: rgb(var(--liquid-fill)); -webkit-backdrop-filter: none; backdrop-filter: none; }
.liquid-tabs::before, .liquid-toolbar::before { scale: 1; transition: scale 350ms cubic-bezier(.2,.9,.25,1.2), box-shadow 200ms; }
.liquid-tabs:has(.liquid-tab:active:not(:disabled))::before { scale: 1.055 1.12; box-shadow: inset 0 1px 2px white, inset 0 -1px 2px rgb(255 255 255 / .5), 0 8px 18px rgb(0 20 25 / .2); }
[data-reduced-motion="true"] .liquid-tabs::before, [data-reduced-motion="true"] .liquid-toolbar::before, [data-reduced-motion="true"] .liquid-toaster .liquid-toast { scale: 1 !important; transition: none !important; }
[data-reduced-motion="true"] .liquid-toaster .liquid-toast * { transition: none !important; animation: none !important; filter: none !important; }
@media (prefers-reduced-motion: reduce) {
  .liquid-tabs::before, .liquid-toolbar::before, .liquid-toaster .liquid-toast { scale: 1 !important; transition: none !important; }
  .liquid-toaster .liquid-toast * { transition: none !important; animation: none !important; filter: none !important; }
}
@media (prefers-reduced-transparency: reduce), (prefers-contrast: more) { .liquid-toaster .liquid-toast { background: rgb(var(--liquid-fill)); -webkit-backdrop-filter: none; backdrop-filter: none; } }
@supports not (backdrop-filter: blur(1px)) { .liquid-toaster .liquid-toast { background: rgb(var(--liquid-fill)); } }
